import sys, json, random, copy
sys.path.insert(0, '/workspace/tmp/t')
from harness import *

MAXOFF = 4611686018427387903

def rand_ranges(rng, strict, n=None):
    n = rng.randint(0, 4) if n is None else n
    out = []
    cur = rng.randint(0, 50)
    for _ in range(n):
        lo = cur
        hi = lo + rng.randint(0, 5)
        out.append([lo, hi])
        cur = hi + (rng.randint(2, 6) if strict else rng.randint(-2, 6))
        cur = max(0, cur)
    return out

def rand_frame(rng, level):
    kinds = ['PADDING','PING','ACK','CRYPTO','STREAM','RESET_STREAM','STOP_SENDING','CLOSE','HANDSHAKE_DONE','UNKNOWN']
    k = rng.choice(kinds)
    if k == 'ACK':
        return {"type":"ACK","ranges":rand_ranges(rng, False)}
    if k == 'CRYPTO':
        return {"type":"CRYPTO","offset":rng.choice([0,1,2,5,17,63,64,MAXOFF-1,MAXOFF]),
                "data_hex":bytes(rng.randrange(256) for _ in range(rng.randint(0,6))).hex()}
    if k == 'STREAM':
        return {"type":"STREAM","id":rng.choice([0,1,2,3,4,6,8,9,12,4096,MAXOFF]),
                "offset":rng.choice([0,1,2,5,17,63,64,65535,MAXOFF-1,MAXOFF]),
                "data_hex":bytes(rng.randrange(256) for _ in range(rng.randint(0,6))).hex(),
                "fin":rng.random()<0.3}
    if k == 'RESET_STREAM':
        return {"type":"RESET_STREAM","id":rng.choice([0,1,2,3,4,8,12]),"final_size":rng.choice([0,1,5,64,65536,MAXOFF])}
    if k == 'STOP_SENDING':
        return {"type":"STOP_SENDING","id":rng.choice([0,1,2,3,4,8,12])}
    if k == 'CLOSE':
        return {"type":"CLOSE","app":rng.random()<0.5,"code":rng.choice([0,1,7,MAXOFF])}
    return {"type":k}

def rand_packet(rng, last):
    level = rng.choice(['I','H','Z','A'] if last else ['I','H','Z'])
    nf = rng.randint(0, 4)
    return {"level":level,"pn":rng.choice([0,1,2,3,5,7,100,MAXOFF]),
            "auth":rng.random()<0.85,
            "frames":[rand_frame(rng, level) for _ in range(nf)]}

def rand_trace(rng, idx):
    n_ev = rng.randint(0, 12)
    evs = []
    t = 0
    for i in range(n_ev):
        t += rng.choice([0,0,1,2,5,11,50])
        r = rng.random()
        if r < 0.25:
            evs.append({"t":t,"op":"key","level":rng.choice(['I','H','Z','A']),
                        "action":rng.choice(['install','discard'])})
        elif r < 0.35:
            evs.append({"t":t,"op":"tick"})
        else:
            n = rng.randint(1, 4)
            pkts = [rand_packet(rng, j == n-1) for j in range(n)]
            evs.append({"t":t,"op":"datagram","bytes":rng.choice([0,100,1199,1200,1201,9000,65535]),"packets":pkts})
    c = {"early":rng.random()<0.5,"overlap":rng.choice(['reject','first']),
         "buffer_packets":rng.choice([0,1,2,4,16,1024]),
         "idle_ms":rng.choice([0,0,1,5,10,100,1000000000]),
         "max_streams_bidi":rng.choice([0,1,2,4,1024]),
         "max_streams_uni":rng.choice([0,1,2,4,1024]),
         "max_stream_data":rng.choice([0,1,16,64,65536]),
         "max_data":rng.choice([0,1,16,64,10**6,MAXOFF]),
         "crypto_limit":rng.choice([0,1,16,64,65536]),
         "sent":{"I":rand_ranges(rng,True),"H":rand_ranges(rng,True),"A":rand_ranges(rng,True)}}
    return {"id":"t%d"%idx,"config":c,"events":evs}

def rand_doc(rng):
    n = rng.randint(0, 3)
    return {"version":1,"traces":[rand_trace(rng,i) for i in range(n)]}

ALLOWED = {
 'dropped': {'LAYOUT','INITIAL_TOO_SMALL','EARLY_REJECTED','KEYS_DISCARDED','BUFFER_FULL','AUTH','CONNECTION_CLOSED'},
 'duplicate': {'DUPLICATE'},
 'buffered': {'NO_KEYS'},
 'accepted': {'OK'},
 'error': {'FRAME_ENCODING_ERROR','PROTOCOL_VIOLATION','STREAM_STATE_ERROR','STREAM_LIMIT_ERROR',
           'FINAL_SIZE_ERROR','FLOW_CONTROL_ERROR','CRYPTO_BUFFER_EXCEEDED'},
}
CODES = ALLOWED['error'] | {'IDLE_TIMEOUT','PEER_APPLICATION_CLOSE','PEER_TRANSPORT_CLOSE'}

def invariants(doc, res, problems):
    assert set(res.keys()) == {'version','results'}, res.keys()
    assert res['version'] == 1
    assert len(res['results']) == len(doc['traces'])
    for tr, r in zip(doc['traces'], res['results']):
        assert set(r.keys()) == {'id','packets','connection','keys','received_total','streams','crypto'}, r.keys()
        assert r['id'] == tr['id']
        want = []
        for ei, ev in enumerate(tr['events']):
            if ev['op'] == 'datagram':
                for pi in range(len(ev['packets'])):
                    want.append((ei, pi))
        got = [(p['event'], p['packet']) for p in r['packets']]
        if got != want:
            problems.append('packet record set/order %s != %s' % (got, want))
        term_idx = None
        for i, p in enumerate(r['packets']):
            assert set(p.keys()) == {'event','packet','status','reason','at_ms','frame'}, p.keys()
            if p['status'] not in ALLOWED: problems.append('bad status %r' % p['status'])
            elif p['reason'] not in ALLOWED[p['status']]: problems.append('bad reason %r for %r' % (p['reason'], p['status']))
            if p['status'] == 'error' and p['reason'] not in ALLOWED['error']: problems.append('bad err code')
            if p['status'] != 'error' and p['frame'] is not None: problems.append('frame non-null for %s' % p['status'])
            if p['frame'] is not None:
                fr = tr['events'][p['event']]['packets'][p['packet']]['frames']
                if not (0 <= p['frame'] < len(fr)): problems.append('frame idx out of range')
            if term_idx is not None and i > term_idx:
                if not (p['status'] == 'dropped' and p['reason'] == 'CONNECTION_CLOSED'):
                    problems.append('record after termination not CONNECTION_CLOSED: %r' % (p,))
            if p['status'] == 'error':
                term_idx = i
            if p['status'] == 'accepted':
                fr = tr['events'][p['event']]['packets'][p['packet']]['frames']
                if any(f['type'] == 'CLOSE' for f in fr):
                    term_idx = i
        c = r['connection']
        assert set(c.keys()) == {'state','code','at_ms','source','peer_code','last_activity_ms'}
        if c['state'] == 'open':
            if not (c['code'] is None and c['at_ms'] is None and c['source'] is None and c['peer_code'] is None):
                problems.append('open conn has non-null fields')
            if any(p['status'] == 'dropped' and p['reason'] == 'CONNECTION_CLOSED' for p in r['packets']):
                problems.append('CONNECTION_CLOSED while open')
        else:
            if c['state'] not in ('closed','idle'): problems.append('bad state')
            if c['code'] not in CODES: problems.append('bad code %r' % c['code'])
            if not isinstance(c['at_ms'], int): problems.append('bad at_ms')
            s = c['source']
            if s is None or set(s.keys()) != {'event','packet','frame'}: problems.append('bad source %r' % (s,))
            if (c['code'] == 'PEER_APPLICATION_CLOSE') != (c['peer_code'] is not None):
                problems.append('peer_code mismatch %r' % (c,))
            if (c['state'] == 'idle') != (c['code'] == 'IDLE_TIMEOUT'): problems.append('idle/code mismatch')
            if any(p['status'] == 'buffered' for p in r['packets']): problems.append('buffered after termination')
        assert set(r['keys'].keys()) == {'I','H','Z','A'}
        for v in r['keys'].values():
            if v not in ('absent','live','discarded'): problems.append('bad key state %r' % v)
        tot = 0
        ids = []
        for s in r['streams']:
            assert set(s.keys()) == {'id','highest','final_size','reset','stopped','delivered_hex'}, s.keys()
            ids.append(s['id'])
            tot += s['highest']
            if len(s['delivered_hex']) // 2 > s['highest']: problems.append('delivered > highest')
            if s['final_size'] is not None and s['highest'] > s['final_size']: problems.append('highest > final_size')
        if ids != sorted(ids): problems.append('streams unsorted')
        if len(set(ids)) != len(ids): problems.append('duplicate stream ids')
        if tot != r['received_total']: problems.append('total mismatch %d != %d' % (tot, r['received_total']))
        lv = [x['level'] for x in r['crypto']]
        if lv != ['I','H','A']: problems.append('crypto levels %r' % lv)
        for x in r['crypto']:
            assert set(x.keys()) == {'level','highest','contiguous_hex'}
            if len(x['contiguous_hex'])//2 > x['highest']: problems.append('crypto contiguous > highest')
        # last activity
        la = c['last_activity_ms']
        acc = [p['at_ms'] for p in r['packets'] if p['status'] == 'accepted']
        if acc and la != max(acc): problems.append('last_activity %r != %r' % (la, max(acc)))
        if not acc and la != 0: problems.append('last_activity should be 0')

# ---- mutation-based invalid testing ----
NUMKEYS = {'t','pn','bytes','offset','id','final_size','code','buffer_packets','idle_ms',
           'max_streams_bidi','max_streams_uni','max_stream_data','max_data','crypto_limit','version'}
STRKEYS = {'op','level','action','overlap','type','data_hex'}
BOOLKEYS = {'auth','fin','app','early'}
OBJKEYS = {'ranges','frames','packets','events','traces','sent','config'}

def mutate(rng, doc):
    """Return a mutated doc that MUST be invalid."""
    kind = rng.randint(0, 6)
    d = copy.deepcopy(doc)
    objs = []
    def walk(o, path):
        if isinstance(o, dict):
            objs.append((o, path))
            for k, v in o.items(): walk(v, path + [k])
        elif isinstance(o, list):
            for i, v in enumerate(o): walk(v, path + [i])
    walk(d, [])
    dicts = [o for o in objs if o[0]]
    if not dicts:
        return {"version":1,"traces":[],"zz":1}
    if kind == 0:   # numeric -> -1
        cand = [(o,k) for o,_ in dicts for k in o if k in NUMKEYS]
        if not cand: return None
        o,k = rng.choice(cand); o[k] = -1
    elif kind == 1: # string -> bogus
        cand = [(o,k) for o,_ in dicts for k in o if k in STRKEYS]
        if not cand: return None
        o,k = rng.choice(cand); o[k] = "\u0000zz"
    elif kind == 2: # bool -> 1
        cand = [(o,k) for o,_ in dicts for k in o if k in BOOLKEYS]
        if not cand: return None
        o,k = rng.choice(cand); o[k] = 1
    elif kind == 3: # container -> 5
        cand = [(o,k) for o,_ in dicts for k in o if k in OBJKEYS]
        if not cand: return None
        o,k = rng.choice(cand); o[k] = 5
    elif kind == 4: # delete a key
        o,_ = rng.choice(dicts)
        if not o: return None
        del o[rng.choice(list(o.keys()))]
    elif kind == 5: # add unknown key
        o,_ = rng.choice(dicts); o['zzz_unknown'] = 1
    else:           # wrong type: int -> string
        cand = [(o,k) for o,_ in dicts for k in o if k in NUMKEYS]
        if not cand: return None
        o,k = rng.choice(cand); o[k] = "3"
    return d

def mutate_struct(rng, doc):
    d = copy.deepcopy(doc)
    if not d['traces']: return None
    tr = rng.choice(d['traces'])
    k = rng.randint(0, 5)
    if k == 0 and len(tr['events']) > 1:
        i = rng.randrange(len(tr['events'])-1)
        tr['events'][i+1]['t'] = tr['events'][i]['t'] - 1
        return d
    if k == 1:
        tr['config']['sent'][rng.choice('IHA')] = [[5,1]]
        return d
    if k == 2:
        tr['config']['sent'][rng.choice('IHA')] = [[0,1],[2,3]]
        return d
    if k == 3:
        tr['config']['sent'][rng.choice('IHA')] = [[10,20],[0,5]]
        return d
    if k == 4:
        evs = [e for e in tr['events'] if e['op'] == 'datagram']
        if not evs: return None
        e = rng.choice(evs)
        e['packets'] = e['packets'][:1] * 17
        return d
    if k == 5:
        evs = [e for e in tr['events'] if e['op'] == 'datagram']
        if not evs: return None
        e = rng.choice(evs)
        e['packets'][0]['frames'] = [{"type":"PING"}] * 65
        return d
    return None

